[
  {
    "id": "must_get_cart",
    "text": "A shopper is obliged to obtain a cart before completing the trip.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "hasCart"
    },
    "justification": "The rule refers only to possession of a cart, not to where carts or exits are located in any particular store."
  },
  {
    "id": "no_exit_without_cart",
    "text": "A shopper is forbidden to leave the store without the cart.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    },
    "justification": "The rule is expressed using the general exit action and cart-possession state, so it applies regardless of the exit's coordinates."
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "A shopper is forbidden to have a cart inside a shelf-lined single-file aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "shelfLinedSingleFileAisle": {
          "and": [
            "adjShelf",
            "singleFileAisle"
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "shelfLinedSingleFileAisle"
        ]
      }
    },
    "justification": "The abstraction identifies narrow shelf aisles by local width and shelf adjacency rather than by fixed cells."
  },
  {
    "id": "no_enter_single_file_with_cart",
    "text": "A shopper is forbidden to move from a wider area into a shelf-lined single-file aisle while still pushing a cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "shelfLinedSingleFileAisle": {
          "and": [
            "adjShelf",
            "singleFileAisle"
          ]
        }
      },
      "events": {
        "enterShelfLinedSingleFileWithCart": {
          "pre": {
            "and": [
              "hasCart",
              "MOVE"
            ]
          },
          "post": "shelfLinedSingleFileAisle"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "enterShelfLinedSingleFileWithCart"
    },
    "justification": "The rule depends on the transition into a locally narrow shelf aisle, a relation that can be detected in any layout."
  },
  {
    "id": "no_cart_interaction_between_opposing_shelves",
    "text": "A shopper is forbidden to interact with shelf goods while holding a cart in a corridor with shelves on opposite sides.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "or": [
            {
              "and": [
                "shelfE",
                "shelfW"
              ]
            },
            {
              "and": [
                "shelfN",
                "shelfS"
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "INTERACT",
          "betweenOpposingShelves"
        ]
      }
    },
    "justification": "Opposing shelf adjacency describes an aisle type independent of the absolute position of that aisle in the store."
  },
  {
    "id": "park_only_to_access_narrow_aisle",
    "text": "If a shopper parks or drops the cart, they are obliged to use that parking to enter a shelf-lined single-file aisle without the cart.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "shelfLinedSingleFileAisle": {
          "and": [
            "adjShelf",
            "singleFileAisle"
          ]
        },
        "uncartedInShelfLinedSingleFileAisle": {
          "and": [
            {
              "not": "hasCart"
            },
            "shelfLinedSingleFileAisle"
          ]
        }
      },
      "events": {
        "cartDropped": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDropped",
      "discharge": "uncartedInShelfLinedSingleFileAisle"
    },
    "justification": "The rule explains cart parking as serving access to locally narrow shelf aisles, not as parking at any particular coordinate."
  },
  {
    "id": "reclaim_parked_cart",
    "text": "After parking or dropping a cart, a shopper is obliged to reclaim a cart before the trip ends.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "cartDropped": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "cartReclaimed": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "cartDropped",
      "discharge": "cartReclaimed"
    },
    "justification": "The rule is based on the general event of relinquishing and reacquiring a cart, independent of where the cart is parked."
  },
  {
    "id": "do_not_linger_in_single_file_aisle",
    "text": "A shopper who enters a shelf-lined single-file aisle without a cart is obliged eventually to leave that aisle.",
    "abstraction": {
      "state_properties": {
        "singleFileAisle": {
          "or": [
            {
              "le": [
                "freeWidthH",
                1
              ]
            },
            {
              "le": [
                "freeWidthV",
                1
              ]
            }
          ]
        },
        "shelfLinedSingleFileAisle": {
          "and": [
            "adjShelf",
            "singleFileAisle"
          ]
        },
        "uncartedInShelfLinedSingleFileAisle": {
          "and": [
            {
              "not": "hasCart"
            },
            "shelfLinedSingleFileAisle"
          ]
        },
        "outsideShelfLinedSingleFileAisle": {
          "not": "shelfLinedSingleFileAisle"
        }
      },
      "events": {}
    },
    "norm": {
      "type": "obligation",
      "trigger": "uncartedInShelfLinedSingleFileAisle",
      "discharge": "outsideShelfLinedSingleFileAisle"
    },
    "justification": "The obligation uses the general local geometry of a narrow shelf aisle rather than the identity of any aisle in a specific floor plan."
  }
]
